type asyncNamedFloat float32

type asyncParameterFixture struct {
	Enabled *asyncNamedBool  `queryParam:"name=enabled"`
	Limit   asyncNamedInt    `queryParam:"name=limit"`
	Ratio   *asyncNamedFloat `queryParam:"name=ratio"`
	Mode    string           `header:"name=X-Mode"`
	Since   time.Time        `queryParam:"name=since"`
	Day     *types.Date      `queryParam:"name=day"`
}

func TestAsyncIntent_RequestParameterReflectionSupportsLinkedScalars(t *testing.T) {
	request := &asyncParameterFixture{}
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "query", "enabled", false))
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "query", "limit", float64(12)))
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "query", "ratio", float64(1.25)))
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "header", "X-Mode", "discrete"))
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "query", "since", "2024-01-15T10:30:00Z"))
	require.NoError(t, flagutil.SetRequestParameter(request, "testPoll", "query", "day", "2024-01-15"))
	require.NotNil(t, request.Enabled)
	assert.False(t, bool(*request.Enabled))
	assert.Equal(t, asyncNamedInt(12), request.Limit)
	require.NotNil(t, request.Ratio)
	assert.Equal(t, asyncNamedFloat(1.25), *request.Ratio)
	assert.Equal(t, "discrete", request.Mode)
	assert.True(t, request.Since.Equal(time.Date(2024, time.January, 15, 10, 30, 0, 0, time.UTC)))
	require.NotNil(t, request.Day)
	assert.Equal(t, "2024-01-15", request.Day.String())
	assert.Error(t, flagutil.SetRequestParameter(request, "testPoll", "query", "limit", float64(40000)))
	assert.Error(t, flagutil.SetRequestParameter(request, "testPoll", "query", "limit", 1.5))
	assert.Error(t, flagutil.SetRequestParameter(request, "testPoll", "query", "since", "yesterday"))
	assert.Error(t, flagutil.SetRequestParameter(request, "testPoll", "query", "day", "2024-01-15T10:30:00Z"))
}
